{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello."
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "आपको gemstone ivory Radha Krishna statue की requirement है ना?"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "ଏ ଆଚ୍ଛା ଦିଆଏ।"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "ଆବେ Ganesh, Vishwakarma, Ma Durga।"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "ये सब दिखाइयो।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "डाइरी वाला मुट्ठी चार चार फुट।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "काल्ह को।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "तो ये आपको 4 feet की जरूरत है।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आप बताइए आपको किस material का चाहिए white Makrana, Vietnam marble या कुछ और?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "कितने piece चाहिए?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "bike वाला मूर्ति दिखाएंगे।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "अभी जो दिखाया था।"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "piece"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "जाना होना चाहिए और इसको वहाँ गया।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "पूछा था कि माल है ना देता है ना।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "दुर्गा माता को जो देता है।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आप अपना नाम बता दीजिए।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "मोहल्ला पाचाली।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "पूछा का नियम, meter ये सब।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "ये details आप seller से discuss कर सकते हैं।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "वो भी एक ठो नहीं दे रहा है।"
    }
  ]
}
